constraints:
1 <= N <= 10^{9}

expected time complexity: O(sqrt(N)*log(N) )
expected auxiliary space: O(sqrt(N))

standard_solution_code:
import sys
sys.setrecursionlimit(10 ** 9)

class Solution:

	def __init__(self):
		self.a = [True] * 100010
		self.primes = [0] * 100010
		self.in_ = 0

	def Sieve(self, n):
		self.a[1] = False
		for i in range(2, int(n ** 0.5) + 1):
			if self.a[i]:
				for j in range(2 * i, n + 1, i):
					self.a[j] = False
		for i in range(2, n + 1):
			if self.a[i]:
				self.primes[self.in_] = i
				self.in_ += 1

	def calc(self, in_, cur, k):
		newCur = self.primes[in_] * self.primes[in_] * cur
		res = 0
		if newCur > k:
			return 0
		res += k // newCur
		res += self.calc(in_ + 1, cur, k)
		res -= self.calc(in_ + 1, newCur, k)
		return res

	def sqNum(self, N):
		self.Sieve(100000)
		ans = self.calc(0, 1, N)
		return ans
